typedef unsigned int nslSourceId;

struct nslSource
{
  bool used;
  bool looping;
  char fileName[48];
  int bank;
  nslSourceId myId;
  float length;
  float paddedLength;
  int type;
  unsigned int gasSourceId;
  float rawVolume;
  float pitch;
  float minDist;
  float maxDist;
};

struct nslSystem
{
  char listenerPo[64];
  nslSource sourceSlots[512];
  char sourcePadding[16384];
  unsigned int sourceSlotsUsedCount;
  char statePadding[52];
  bool on;
};

extern nslSystem nsl;
void _nslInitialized();
void nslFatal(const char *, ...);
extern "C" char *strncpy(char *, const char *, unsigned int);
extern "C" char *strupr(char *);
extern "C" int strcmp(const char *, const char *);

asm(".equ nsl,0x0049B5F0");
asm(".equ _nslInitialized__Fv,0x0038BDF8");
asm(".equ nslFatal__FPCce,0x00391420");
asm(".equ strncpy,0x003F05A8");
asm(".equ strupr,0x003EF9A8");
asm(".equ strcmp,0x003EFC08");

#define NSL_INVALID_ID 0
#define ASSERT_NSL_INITIALIZED() _nslInitialized()

nslSourceId nslGetSource( const char *soundSourceName, bool fatal )
{
  if (!nsl.on) return 0;
  ASSERT_NSL_INITIALIZED();
  char checkName[48];
  strncpy(checkName, soundSourceName, 48);
  checkName[47] = '\0';
  strupr(checkName);
  for (unsigned int i=0; i < nsl.sourceSlotsUsedCount; i++) 
  {
    if (strcmp(checkName, nsl.sourceSlots[i].fileName)==0) 
    {
      return nsl.sourceSlots[i].myId;
    }
  }

  if (fatal)
  {
    nslFatal("nslGetSource: bad source name\n");
  }
  return NSL_INVALID_ID;
}
